const b=load("freshBass");const lines=b.data.document.trim().split("\n");
const ov=lines.filter(l=>l.startsWith("OVERLAY ")).map(l=>JSON.parse(l.slice(8)));
const notes=lines.filter(l=>l.startsWith("EVENT ")).map(l=>{let p=l.split(" ");return{id:p[1],at:p[3],duration:p[4],pitch:p[5],velocity:p[6],channel:p[7],mute:p[8]};});
const num=s=>s.includes("/")?s.split("/").map(Number).reduce((a,b)=>a/b):+s;
const frac=(n,d=1024)=>{let v=Math.round(n*d);while(v%2===0&&d>1){v/=2;d/=2;}return d===1?String(v):`${v}/${d}`;};
let patch=["DOC ghostnote-document 1.0 patch","BASE "+JSON.stringify(b.authority.base),"FIELDS id clip at duration pitch velocity channel mute"],changes=[];
for(const n of notes){
 const nom=ov.find(o=>o.type==="nominal"&&o.data.event===n.id&&o.state==="current");
 const gr=ov.find(o=>o.type==="groove"&&o.data.event===n.id&&o.state==="current");
 const source=num(nom.data.at)+(num(n.at)-num(nom.data.at))/2;
 const at= Math.round(source*512)/512;
 if(at!==num(n.at)) patch.push(`UPDATE ${n.id} ${JSON.stringify({at:frac(at)})}`);
 const newNom={...nom};delete newNom.basis;patch.push("OVERLAY_PUT "+JSON.stringify(newNom));
 const newGr=JSON.parse(JSON.stringify(gr));delete newGr.basis;newGr.id=gr.id+"_half";newGr.provenance={kind:"declared",source:"User requested half the laid-back timing",method:"scale original onset deviation from preserved nominal rhythm by 1/2"};
 newGr.data.template=frac((num(n.at)-num(nom.data.at))/2);
 newGr.data.sourceAt=frac(source);newGr.data.atDelta=frac(at-source);
 patch.push("OVERLAY_PUT "+JSON.stringify(newGr));
 changes.push({id:n.id,before:n.at,after:frac(at),nominal:nom.data.at});
}
store("halfExpected",changes);store("halfPatch",patch.join("\n"));
